@Override
    public void onHackComplete(Level world, BlockPos pos, Player player) {
        if (world instanceof ServerLevel serverLevel) {
            BlockState state = world.getBlockState(pos);

            // set it to inactive initially, so any pending ticks don't just wake it up again
            world.setBlock(pos, state.setValue(PHASE, SculkSensorPhase.INACTIVE), Block.UPDATE_ALL);

            // and once the cooldown duration is passed, set it into cooldown mode for the silencing duration
            serverLevel.getServer().tell(new TickTask(serverLevel.getServer().getTickCount() + SculkSensorBlock.COOLDOWN_TICKS + 1, () -> {
                if (world.getBlockState(pos).getBlock() instanceof SculkSensorBlock) {
                    world.setBlock(pos, state.setValue(PHASE, COOLDOWN).setValue(SculkSensorBlock.POWER, 0), Block.UPDATE_ALL);
                    world.scheduleTick(pos, state.getBlock(), SILENCE_TIME);
                    world.updateNeighborsAt(pos, state.getBlock());
                    world.updateNeighborsAt(pos.below(), state.getBlock());
                }
            }));
        }
    }

private void checkStateUpdates(ItemStack loadedStack, boolean didWork) {
        BlockState state = getBlockState();
        if (state.getBlock() == ModBlocks.UV_LIGHT_BOX.get()) {
            boolean loaded = state.getValue(UVLightBoxBlock.LOADED);
            boolean updateNeeded = false;
            if (loaded == loadedStack.isEmpty()) {
                state = state.setValue(UVLightBoxBlock.LOADED, !loadedStack.isEmpty());
                updateNeeded = true;
            }
            if (didWork != getBlockState().getValue(UVLightBoxBlock.LIT)) {
                state = state.setValue(UVLightBoxBlock.LIT, didWork);
                updateNeeded = true;
            }
            long now = nonNullLevel().getGameTime();
            if (updateNeeded) {
                if (now - lastStateUpdateTime > 10) {
                    updateBlockStateImmediate(state, now);
                } else {
                    pendingState = state;
                }
            } else if (pendingState != null && now - lastStateUpdateTime > 10) {
                updateBlockStateImmediate(pendingState, now);
            }
        }
    }

@Override
    public void tickServer() {
        super.tickServer();

        discharging = false;
        charging = false;

        chargingStackSynced = itemHandler.getStackInSlot(CHARGE_INVENTORY_INDEX);

        int airToTransfer = (int) (PneumaticValues.CHARGING_STATION_CHARGE_RATE * getSpeedMultiplierFromUpgrades());

        for (IAirHandler itemAirHandler : findChargeable()) {
            float itemPressure = itemAirHandler.getPressure();
            float itemVolume = itemAirHandler.getVolume();
            float chargerPressure = getPressure();
            float delta = Math.abs(chargerPressure - itemPressure) / 2.0F;
            int airInItem = itemAirHandler.getAir();

            if (PneumaticCraftUtils.epsilonEquals(chargerPressure, 0f) && delta < 0.1f) {
                // small kludge to get last tiny bit of air out of an item (arithmetic rounding)
                itemAirHandler.addAir(-airInItem);
            } else if (itemPressure > chargerPressure + 0.01F && itemPressure > 0F) {
                // move air from item to charger
                int airToMove = Math.min(Math.min(airToTransfer, airInItem), (int) (delta * airHandler.getVolume()));
                itemAirHandler.addAir(-airToMove);
                this.addAir(airToMove);
                discharging = true;
            } else if (itemPressure < chargerPressure - 0.01F && itemPressure < itemAirHandler.maxPressure()) {
                // move air from charger to item
                int maxAirInItem = (int) (itemAirHandler.maxPressure() * itemVolume);
                float boost = chargerPressure < 15f ? 1f : 1f + (chargerPressure - 15f) / 5f;
                int airToMove = Math.min(Math.min((int)(airToTransfer * boost), airHandler.getAir()), maxAirInItem - airInItem);
                airToMove = Math.min((int) (delta * itemVolume), airToMove);
                itemAirHandler.addAir(airToMove);
                this.addAir(-airToMove);
                charging = true;
            }
        }

        boolean shouldEmit = rsController.shouldEmit();
        if (oldRedstoneStatus != shouldEmit) {
            if (nonNullLevel().getGameTime() - lastRedstoneUpdate > MAX_REDSTONE_UPDATE_FREQ) {
                updateRedstoneOutput();
            } else {
                pendingRedstoneStatus = shouldEmit ? 1: 0;
            }
        } else if (pendingRedstoneStatus != -1 && nonNullLevel().getGameTime() - lastRedstoneUpdate > MAX_REDSTONE_UPDATE_FREQ) {
            updateRedstoneOutput();
        }

        airHandler.setSideLeaking(!upgradeOnly && hasNoConnectedAirHandlers() ? getRotation() : null);
    }

@Override
    public void tick(BlockEntity ownerTE) {
        Level world = Objects.requireNonNull(ownerTE.getLevel());
        Direction actualLeakDir = leakDir;

        if (!world.isClientSide) {
            if (pendingAir != 0) {
                // add any saved air if this is being restored from item stack component data
                // need to wait till now to ensure saved volume upgrades are also accounted for
                addAir(pendingAir);
                pendingAir = 0;
                if (getPressure() > getDangerPressure()) {
                    // shouldn't happen but just in case
                    setPressure(getDangerPressure() - 0.1f);
                }
            }

            // server
            disperseAir(ownerTE);

            BlockPos pos = ownerTE.getBlockPos();
            if (safetyLeakDir != null) {
                float pressure = getPressure();
                if (!safetyLeaking && safetyPredicate.test(pressure)) {
                    safetyLeaking = true;
                } else if (safetyLeaking && !safetyPredicate.test(pressure + 0.2f)) {
                    safetyLeaking = false;
                }
                // also cap pressure at critical level (it's still possible for air to added faster than it can vent)
                if (pressure >= getCriticalPressure()) {
                    int wanted = (int)(getCriticalPressure() * getVolume());
                    addAir(wanted - getAir());
                }
            } else if (Objects.requireNonNull(world.getServer()).getTickCount() > 20) {
                // little kludge: no overpressure checks right after server starts up (just to be safe)
                doOverpressureChecks(ownerTE, world, pos);
            }

            actualLeakDir = safetyLeaking ? safetyLeakDir : leakDir;
            if (prevLeakDir != actualLeakDir || actualLeakDir != null && (world.getGameTime() & 0x1f) == 0) {
                // if leak status changes, sync pressure & leak dir to the client
                // OR if already leaking, periodically sync pressure & leak dir to the client
                NetworkHandler.sendToAllTracking(PacketUpdatePressureBlock.create(ownerTE.getBlockPos(),
                        anyConnectableFace(), actualLeakDir, getAir()
                ), ownerTE);
            }

            prevAir = getAir();
            prevLeakDir = actualLeakDir;
        }

        if (actualLeakDir != null && getAir() != 0) {
            handleAirLeak(ownerTE, actualLeakDir);
        }
    }

public static void handle(PacketHackingBlockStart message, IPayloadContext ctx) {
        Player player = ctx.player();

        if (ctx.flow().isClientbound()) {
            // client
            CommonArmorHandler.getHandlerForPlayer()
                    .getExtensionData(CommonUpgradeHandlers.hackHandler)
                    .setHackedBlockPos(GlobalPos.of(player.level().dimension(), message.pos));

            RenderBlockTarget target = ClientArmorRegistry.getInstance()
                    .getClientHandler(CommonUpgradeHandlers.blockTrackerHandler, BlockTrackerClientHandler.class)
                    .getTargetForCoord(message.pos);
            if (target != null) {
                target.onHackConfirmedByServer();
            }
        } else if (player instanceof ServerPlayer sp) {
            // server
            CommonArmorHandler handler = CommonArmorHandler.getHandlerForPlayer(player);
            if (handler.upgradeUsable(CommonUpgradeHandlers.blockTrackerHandler, true)) {
                handler.getExtensionData(CommonUpgradeHandlers.hackHandler)
                        .setHackedBlockPos(GlobalPos.of(player.level().dimension(), message.pos));
                NetworkHandler.sendToPlayer(message, sp);
            }
        }
    }

private Set<PressureTubeBlockEntity> computeConnectedTubes(Level level, BlockPos initialPos) {
        Set<PressureTubeBlockEntity> tubes = new HashSet<>();
        Set<BlockPos> traversedPositions = new HashSet<>();
        Deque<BlockPos> pendingPositions = new ArrayDeque<>(List.of(initialPos));

        while (!pendingPositions.isEmpty()) {
            BlockPos pos = pendingPositions.pop();
            BlockState state = level.getBlockState(pos);
            if (state.getBlock() instanceof ITubeNetworkConnector nc) {
                PneumaticCraftUtils.getBlockEntityAt(level, pos, PressureTubeBlockEntity.class).ifPresent(tubes::add);
                for (Direction dir : DirectionUtil.VALUES) {
                    BlockPos pos1 = pos.relative(dir);
                    if (!level.isLoaded(pos1)) continue;
                    BlockState state1 = level.getBlockState(pos1);
                    if (state1.getBlock() instanceof ITubeNetworkConnector nc1
                            && nc1.canConnectToNetwork(level, pos1, dir.getOpposite(), state1)
                            && nc.canConnectToNetwork(level, pos, dir, state)
                            && traversedPositions.add(pos1))
                    {
                        pendingPositions.add(pos1);
                    }
                }
            }
        }
        return tubes;
    }

@Override
    public void tickClient(ICommonArmorHandler armorHandler, boolean isEnabled) {
        if (!isEnabled) return;

        int rangeUpgrades = armorHandler.getUpgradeCount(EquipmentSlot.HEAD, ModUpgrades.RANGE.get());
        Player player = armorHandler.getPlayer();

        // check for filter change and recompile filter if necessary
        ItemStack helmetStack = player.getItemBySlot(EquipmentSlot.HEAD);
        String filterStr = helmetStack.isEmpty() ? "" : PneumaticArmorItem.getEntityFilter(helmetStack);
        if (!entityFilter.toString().equals(filterStr)) {
            EntityFilter newFilter = EntityFilter.fromString(filterStr);
            if (newFilter != null) {
                entityFilter = newFilter;
            }
        }

        // find applicable entities and create/update render targets for them as needed
        double entityTrackRange = ENTITY_TRACKING_RANGE + rangeUpgrades * PneumaticValues.RANGE_UPGRADE_HELMET_RANGE_INCREASE_ENTITY;
        AABB bbBox = getAABBFromRange(player, rangeUpgrades);
        List<Entity> entities = armorHandler.getPlayer().level().getEntitiesOfClass(Entity.class, bbBox,
                new EntityTrackerSelector(player, entityFilter, entityTrackRange));
        for (Entity entity : entities) {
            RenderEntityTarget target = targets.get(entity.getId());
            if (target != null) {
                target.ticksExisted = Math.abs(target.ticksExisted); // cancel lost targets
            } else {
                targets.put(entity.getId(), new RenderEntityTarget(entity));
            }
        }

        // prune no-longer-applicable entities from the render target list
        IntList toRemove = new IntArrayList();
        targets.forEach((entityId, target) -> {
            if (!target.entity.isAlive() || player.distanceTo(target.entity) > entityTrackRange + 5 || !entityFilter.test(target.entity)) {
                if (target.ticksExisted > 0) {
                    target.ticksExisted = -60;
                } else if (target.ticksExisted == -1) {
                    toRemove.add(entityId.intValue());
                }
            }
        });
        toRemove.forEach(targets::remove);

        // handle tick logic for every valid render target
        List<Component> text = new ArrayList<>();
        for (RenderEntityTarget target : targets.values()) {
            boolean wasNegative = target.ticksExisted < 0;
            target.ticksExisted += armorHandler.getSpeedFromUpgrades(EquipmentSlot.HEAD);
            if (target.ticksExisted >= 0 && wasNegative) target.ticksExisted = -1;
            target.tick();
            if (target.isLookingAtTarget) {
                if (target.isInitialized()) {
                    text.add(target.entity.getDisplayName().copy().withStyle(ChatFormatting.GRAY));
                    text.addAll(target.getEntityText());
                } else {
                    text.add(xlate("pneumaticcraft.entityTracker.info.acquiring").withStyle(ChatFormatting.GRAY));
                }
            }
        }
        if (text.isEmpty()) {
            String f = entityFilter.toString();
            text.add(xlate("pneumaticcraft.gui.entityFilter").append(": " + (f.isEmpty() ? "-" : f)));
        }
        entityTrackInfo.setText(text);
    }

private void handleKick(Player player, int upgrades) {
        long now = Util.getMillis();
        long prev = lastServerRecv.getOrDefault(player.getUUID(), 0L);
        if (now - prev < MIN_KICK_INTERVAL) {
            return;
        }
        lastServerRecv.put(player.getUUID(), now);

        Vec3 lookVec = new Vec3(player.getLookAngle().x, Math.max(0, player.getLookAngle().y), player.getLookAngle().z).normalize();

        double playerFootY = player.getY() - player.getBbHeight() / 2;
        AABB box = new AABB(player.getX(), playerFootY, player.getZ(), player.getX(), playerFootY, player.getZ())
                .inflate(1.5, 1.5, 1.5).move(lookVec);
        List<Entity> entities = player.level().getEntities(player, box);
        if (entities.isEmpty()) return;
        entities.sort(Comparator.comparingDouble(o -> o.distanceToSqr(player)));

        Entity target = entities.getFirst();
        if (!target.skipAttackInteraction(player)) {
            if (target instanceof LivingEntity living) {
                target.hurt(target.damageSources().playerAttack(player), 3.0f + upgrades * 0.5f);
                living.setJumping(true);
            }
            target.setOnGround(false);
            target.horizontalCollision = false;
            target.verticalCollision = false;
            target.setDeltaMovement(target.getDeltaMovement().add(lookVec.scale(1.0 + upgrades * 0.5)).add(0, upgrades * 0.1, 0));
            player.level().playSound(null, target.getX(), target.getY(), target.getZ(), ModSounds.PUNCH.get(), SoundSource.PLAYERS, 1f, 1f);
            NetworkHandler.sendToAllTracking(PacketSetEntityMotion.create(target, target.getDeltaMovement()), target);
            NetworkHandler.sendToAllTracking(PacketSpawnParticle.oneParticle(ParticleTypes.EXPLOSION, target.position().toVector3f(), PARTICLE_SPEED), target);
            CommonArmorHandler.getHandlerForPlayer(player).addAir(EquipmentSlot.FEET, -PneumaticValues.PNEUMATIC_KICK_AIR_USAGE * upgrades);
        }
    }

