@Override
    public void tick(ICommonArmorHandler commonArmorHandler, boolean enabled) {
        Player player = commonArmorHandler.getPlayer();

        if (player.level().isClientSide || player.isSpectator() || !enabled
                || (player.level().getGameTime() & 0x3) != 0
                || !commonArmorHandler.hasMinPressure(EquipmentSlot.CHEST))
            return;

        int magnetRadius = PneumaticValues.MAGNET_BASE_RANGE
                + Math.min(commonArmorHandler.getUpgradeCount(EquipmentSlot.CHEST, ModUpgrades.MAGNET.get()), PneumaticValues.MAGNET_MAX_UPGRADES);
        int magnetRadiusSq = magnetRadius * magnetRadius;

        AABB box = new AABB(player.blockPosition()).inflate(magnetRadius);
        List<Entity> itemList = player.getCommandSenderWorld().getEntitiesOfClass(Entity.class, box,
                e -> (e instanceof ExperienceOrb || e instanceof ItemEntity) && e.isAlive());

        Vec3 playerVec = player.position();
        for (Entity item : itemList) {
            if (item instanceof ItemEntity && ((ItemEntity) item).hasPickUpDelay()) continue;

            if (item.position().distanceToSqr(playerVec) <= magnetRadiusSq
                    && !ItemRegistry.getInstance().shouldSuppressMagnet(item)
                    && !item.getPersistentData().getBoolean(Names.PREVENT_REMOTE_MOVEMENT)) {
                if (!commonArmorHandler.hasMinPressure(EquipmentSlot.CHEST)) break;
                item.setPos(player.getX(), player.getY(), player.getZ());
                if (item instanceof ItemEntity) ((ItemEntity) item).setPickUpDelay(0);
                commonArmorHandler.addAir(EquipmentSlot.CHEST, -ConfigHelper.common().armor.magnetAirUsage.get());
            }
        }
    }

public void activateNukeVirus(int pos) {
        int neighbour = getHackedNeighbour(pendingNukePos);
        if (neighbour >= 0) {
            boolean found = false;
            Node neighbourNode = getNodeAt(neighbour);
            if (neighbourNode != null) {
                for (Pair<Integer, Float> conn : neighbourNode.outGoingHacks) {
                    if (conn.getLeft() == pendingNukePos) {
                        conn.setValue(1f);
                        found = true;
                    }
                }
                if (!found) {
                    neighbourNode.outGoingHacks.add(Pair.of(pendingNukePos, 1f));
                }
                Node node = getNodeAt(pos);
                if (node != null) {
                    node.setHackProgress(pos, 1f, false);
                }
                if (controller != null) controller.getHacker().playSound(SoundEvents.GENERIC_EXPLODE.value(), 1f, 1f);
                nukeVirusCooldown = 60;
            }
        }
        pendingNukePos = -1;
    }

private void processApplicableRecipes() {
        for (ApplicableRecipe applicableRecipe : applicableRecipes) {
            PressureChamberRecipe recipe = applicableRecipe.recipe;
            float requiredPressure = recipe.getCraftingPressure(itemsInChamber, applicableRecipe.slots);
            boolean pressureOK = requiredPressure <= getPressure() && requiredPressure > 0F
                    || requiredPressure >= getPressure() && requiredPressure < 0F;
            if (Math.abs(requiredPressure) < Math.abs(recipePressure)) {
                recipePressure = requiredPressure;
            }
            if (pressureOK) {
                // let's craft! (although if the output handler is full, we won't...)
                isSufficientPressureInChamber = true;
                if (giveOutput(recipe.craftRecipe(itemsInChamber, applicableRecipe.slots, true), true)
                        && giveOutput(recipe.craftRecipe(itemsInChamber, applicableRecipe.slots, false), false)) {
                    if (nonNullLevel().getGameTime() - lastSoundTick > 5) {
                        nonNullLevel().playSound(null, getBlockPos(), SoundEvents.CHICKEN_EGG, SoundSource.BLOCKS, 0.7f, 0.8f);
                        lastSoundTick = nonNullLevel().getGameTime();
                    }
                }
                // Craft at most one recipe each tick; this is because crafting changes the contents of the
                // chamber, possibly invalidating other applicable recipes.  Modifying the chamber's contents
                // automatically triggers a rescan for applicable recipes on the next tick.
                break;
            }
        }
    }

private void handleAmmoRepair(ItemStack stack, Level world, Minigun minigun) {
        if (minigun.getPlayer().containerMenu instanceof MinigunMagazineMenu) {
            return;  // avoid potential item duping or other shenanigans
        }
        int itemLife = minigun.getUpgrades(ModUpgrades.ITEM_LIFE.get());
        if (itemLife > 0) {
            MagazineHandler handler = getMagazine(stack);
            boolean repaired = false;
            float pressure = minigun.getAirCapability().orElseThrow(RuntimeException::new).getPressure();
            if (world.getGameTime() % (200 - itemLife * 35L) == 0) {
                for (int i = 0; i < handler.getSlots() && pressure > 0.25f; i++) {
                    ItemStack ammo = handler.getStackInSlot(i);
                    if (ammo.getItem() instanceof AbstractGunAmmoItem && ammo.getDamageValue() > 0) {
                        ammo.setDamageValue(ammo.getDamageValue() - 1);
                        if (!minigun.getPlayer().isCreative()) {
                            minigun.getAirCapability().ifPresent(h -> h.addAir(-(100 * itemLife)));
                        }
                        pressure = minigun.getAirCapability().orElseThrow(RuntimeException::new).getPressure();
                        repaired = true;
                    }
                }
            }
            if (repaired) {
                handler.save();
            }
        }
    }

