@Override
    public void tickServer() {
        super.tickServer();

        isCoreLoaded = inv.isCorePresent();

        if (isOpen() && isCoreLoaded && inv.getStats().getUnusedPercentage() > 0 && getPressure() <= getMinWorkingPressure()) {
            if ((nonNullLevel().getGameTime() & 0xf) == 0) {
                scanForEntities();
            }
            Vec3 trapVec = Vec3.atCenterOf(worldPosition);
            double min = nonNullLevel().getFluidState(worldPosition).getType() == Fluids.WATER ? 2.5 : 1.75;
            for (Mob e : targetEntities) {
                if (!e.isAlive() || e.getTags().contains(DEFENDER_TAG)) continue;
                // kludge: mobs in water seem a bit flaky about getting close enough so increase the absorb dist a bit
                if (e.distanceToSqr(trapVec) <= min) {
                    absorbEntity(e);
                    addAir((int) (PneumaticValues.USAGE_VACUUM_TRAP * e.getHealth()));
                } else {
                    e.getNavigation().moveTo(trapVec.x(), trapVec.y(), trapVec.z(), 1.2);
                }
            }
        }
        if (!isCoreLoaded)
            problem = Problems.NO_CORE;
        else if (inv.getStats().getUnusedPercentage() == 0)
            problem = Problems.CORE_FULL;
        else if (!isOpen())
            problem = Problems.TRAP_CLOSED;
        else
            problem = Problems.OK;
    }

@Override
    public void tick(ICommonArmorHandler commonArmorHandler, boolean enabled) {
        if (commonArmorHandler.isOnCooldown(EquipmentSlot.FEET)) {
            // putting the boots on cooldown is a way for other mods to temporarily suppress jet boots
            return;
        }

        int jetbootsCount = commonArmorHandler.getUpgradeCount(EquipmentSlot.FEET, ModUpgrades.JET_BOOTS.get());
        if (jetbootsCount == 0) return;

        int jetbootsAirUsage = 0;

        Player player = commonArmorHandler.getPlayer();
        JetBootsStateTracker.JetBootsState jbState = JetBootsStateTracker.getTracker(player).getJetBootsState(player);
        JetBootsLocalState jbLocal = commonArmorHandler.getExtensionData(this);

        if (commonArmorHandler.hasMinPressure(EquipmentSlot.FEET)) {
            boolean vibration = !player.level().isClientSide() && player.tickCount % 10 == 0;
            if (jbState.isActive()) {
                if (jbState.isBuilderMode() && jetbootsCount >= BUILDER_MODE_LEVEL) {
                    // builder mode - rise vertically (or hover if sneaking and firing)
                    setYMotion(player, player.isShiftKeyDown() ? 0 : 0.15 + 0.15 * (jetbootsCount - 3));
                    jetbootsAirUsage = (int) (ConfigHelper.common().armor.jetBootsAirUsage.get() * jetbootsCount / 2.5F);
                    if (vibration) {
                        player.gameEvent(ModGameEvents.JET_BOOTS_FLY_BUILDER);
                    }
                } else {
                    // jetboots firing - move in direction of looking
                    Vec3 lookVec = player.getLookAngle().scale(0.3 * jetbootsCount);
                    jbLocal.updateAccel(lookVec);
                    lookVec = jbLocal.getEffectiveMotion(lookVec, player.isFallFlying());
                    player.setDeltaMovement(lookVec.x, player.onGround() ? 0 : lookVec.y, lookVec.z);
                    jetbootsAirUsage = jbLocal.calcAirUsage(jetbootsCount);
                    if (vibration) {
                        player.gameEvent(ModGameEvents.JET_BOOTS_FLY);
                    }
                }
                if (player.isInWater()) jetbootsAirUsage *= 4;
                jbLocal.tickActive();
            } else if (jbState.isEnabled() && !isOnGround(player) && !player.isFallFlying()) {
                // jetboots not firing, but enabled - slowly descend (or hover if enough upgrades)
                // and bring player to complete halt if flight stabilizers and not actively moving forward/sideways
                boolean reallyHovering = jbLocal.canHover() && (!jbLocal.isSmartHover() || jbLocal.isHovering());
                boolean stopped = jbLocal.isFlightStabilizers()
                        && jetbootsCount >= STABILIZERS_LEVEL
                        && PneumaticCraftUtils.epsilonEquals(player.zza, 0f)
                        && PneumaticCraftUtils.epsilonEquals(player.xxa, 0f);
                double xMotion = stopped ? 0 : player.getDeltaMovement().x;
                double yMotion = reallyHovering ? (player.isShiftKeyDown() ? -0.45 : -0.1 + 0.02 * jetbootsCount) : player.getDeltaMovement().y;
                double zMotion = stopped ? 0 : player.getDeltaMovement().z;
                player.setDeltaMovement(new Vec3(xMotion, yMotion, zMotion));
                if (vibration && player.getKnownMovement().lengthSqr() > 0.03) {
                    player.gameEvent(jbState.isBuilderMode() ? ModGameEvents.JET_BOOTS_FLY_BUILDER : ModGameEvents.JET_BOOTS_FLY);
                }
                if (reallyHovering) player.fallDistance = 0;
                jetbootsAirUsage = reallyHovering ? (int) (ConfigHelper.common().armor.jetBootsAirUsage.get() * (player.isShiftKeyDown() ? 0.25F : 0.5F)) : 0;
                jbLocal.resetAccel();
            } else if (isOnGround(player)) {
                jbLocal.setHovering(false);
            } else {
                jbLocal.resetAccel();
            }
        } else {
            // insufficient pressure!
            if (jbState.isEnabled() && !player.onGround() && !player.isFallFlying() && jbLocal.isHovering()) {
                // still active and in the air: using minimal air here keeps the boots running
                // and thus avoids triggering multiple looping sounds (see "jet boots starting up" code below)
                jetbootsAirUsage = 1;
            }
            setJetBootsActive(commonArmorHandler,false);
        }

        if (jetbootsAirUsage != 0 && !player.level().isClientSide) {
            if (jbLocal.getPrevJetBootsAirUsage() == 0) {
                // jet boots starting up
                NetworkHandler.sendToAllTracking(new PacketPlayMovingSound(MovingSounds.Sound.JET_BOOTS, MovingSoundFocus.of(player)), player.level(), player.blockPosition());
                ModCriterionTriggers.FLIGHT.get().trigger((ServerPlayer) player);
            }
            if (player.horizontalCollision) {
                double vel = player.getDeltaMovement().length();
                if (player.level().getDifficulty() == Difficulty.HARD) {
                    vel *= 2;
                } else if (player.level().getDifficulty() == Difficulty.NORMAL) {
                    vel *= 1.5;
                }
                if (vel > 2) {
                    player.playSound(vel > 2.5 ? SoundEvents.GENERIC_BIG_FALL : SoundEvents.GENERIC_SMALL_FALL, 1.0F, 1.0F);
                    player.hurt(player.damageSources().flyIntoWall(), (float) vel);
                    ModCriterionTriggers.FLY_INTO_WALL.get().trigger((ServerPlayer) player);
                }
            }
            commonArmorHandler.addAir(EquipmentSlot.FEET, -jetbootsAirUsage);

            if (player.position().y > player.level().getMaxBuildHeight() + ConfigHelper.common().armor.jetBootsHeightLimit.get()) {
                player.getCooldowns().addCooldown(ModItems.PNEUMATIC_BOOTS.get(), 20);
            }
        }
        jbLocal.setPrevJetBootsAirUsage(jetbootsAirUsage);

    }

public boolean initiateNukeVirus(int pos) {
        Validate.isTrue(pos >= 0 && pos < GRID_SIZE, "nuke position " + pos + " out of range!");
        Node node = getNodeAt(pos);
        if (node != null && pendingNukePos < 0 && isNukeVirusReady()
                && node.type != NetworkComponentType.DIAGNOSTIC_SUBROUTINE
                && node.type != NetworkComponentType.NETWORK_REGISTRY)
        {
            pendingNukePos = pos;
            return true;
        } else {
            return false;
        }
    }

public boolean payout() {
        BlockEntity returning = getReturningTileEntity();
        if (pendingPayments > 0) {
            final int pay0 = Math.min(pendingPayments, 50);
            int paying = getInput().apply(
                    itemStack -> IOHelper.getInventoryForBlock(returning).map(h -> getInput().findSpaceInItemOutput(h, pay0)).orElse(0),
                    fluidStack -> IOHelper.getFluidHandlerForBlock(returning).map(h -> getInput().findSpaceInFluidOutput(h, pay0)).orElse(0)
            );
            if (paying > 0) {
                pendingPayments -= paying;
                getInput().accept(
                        itemStack -> DroneRegistry.getInstance().deliverItemsAmazonStyle(returningPos, AmadronUtil.buildStacks(itemStack, paying)),
                        fluidStack -> DroneRegistry.getInstance().deliverFluidAmazonStyle(returningPos, AmadronUtil.buildFluidStack(fluidStack, paying)));
                return true;
            }
        }
        return false;
    }

public void tick() {
        int currentTemp = logic.getTemperatureAsInt();

        if (shouldSyncNow()) {
            // large temperature delta: sync immediately
            this.syncedTemp = currentTemp;
            syncTimer = -1;
        } else if (currentTemp != syncedTemp) {
            // small temperature delta: schedule a sync to happen in 60 ticks, unless one is already scheduled
            if (syncTimer == -1) syncTimer = SYNC_RATE;
            pendingTemp = currentTemp;
        }

        if (syncTimer >= 0) {
            if (--syncTimer == -1) {
                this.syncedTemp = pendingTemp;
            }
        }
    }

public void tick() {
        if (hackComplete) return;

        isStarted = true;

        if (stopWormTimer > 0) {
            stopWormTimer--;
        }
        if (nukeVirusCooldown > 0) {
            nukeVirusCooldown--;
        }

        allConnections.clear();
        int nonNullNodes = 0;
        int completeNodes = 0;
        for (int i = 0; i < nodes.length; i++) {
            Node node = getNodeAt(i);
            if (node == null) continue;
            nonNullNodes++;

            int f = node.fortification;
            node.tick();
            if (controller != null && f < NODE_FORTIFICATION_TIME && node.fortification == NODE_FORTIFICATION_TIME) {
                controller.onNodeFortified(this, i);
            }

            if (side == HackingSide.AI && isAwake() && (isDummy() || node.isHacked()) && node.outGoingHacks.isEmpty()) {
                // start the trace to all neighbouring nodes
                for (int neighbourPos : getNeighbours(i)) {
                    Node neighbourNode = getNodeAt(neighbourPos);
                    if (neighbourNode != null && (isDummy() || !neighbourNode.isHacked())) {
                        // found an unhacked neighbour
                        node.startHacking(i, neighbourPos);
                    }
                }
            }

            if (pendingNukePos == i) {
                activateNukeVirus(i);
            }

            // update all in-progress connections
            int finishedConns = 0;
            for (Pair<Integer, Float> conn : node.outGoingHacks) {
                if (conn.getValue() < 1F) {
                    if (stopWormTimer == 0) {
                        Node targetNode = getNodeAt(conn.getKey());
                        if (targetNode != null) {
                            conn.setValue(Math.min(1F, conn.getValue() + targetNode.getProgressPerTick()));
                            targetNode.setHackProgress(conn.getKey(), conn.getValue(), true);
                        }
                    }
                } else {
                    finishedConns++;
                }
                allConnections.add(new ConnectionEntry(i, conn.getKey(), conn.getValue()));
            }
            if (finishedConns == node.outGoingHacks.size() && !node.outGoingHacks.isEmpty()) completeNodes++;
        }
        if (completeNodes >= nonNullNodes) {
            hackComplete = true;
        }
    }

@Override
    public void tickServer() {
        super.tickServer();

        int defenderChance = nonNullLevel().getDifficulty() == Difficulty.EASY ? 40 : 20;
        if (mode == Mode.RUNNING && getPressure() <= getMinWorkingPressure()) {
            addAir(PneumaticValues.USAGE_SPAWNER_EXTRACTOR);
            if (progress >= 1f) {
                extractSpawnerCore();
            } else if (currentSpeed > 0.1f && nonNullLevel().random.nextInt(defenderChance) == 0) {
                // spawn defending entities; each entity nearby will slow down the extraction process
                nonNullLevel().getBlockEntity(worldPosition.below(), BlockEntityType.MOB_SPAWNER).ifPresent(te -> {
                    if (!trySpawnDefender(te)) {
                        spawnFailures++;
                    }
                });
            }
        }
        if ((nonNullLevel().getGameTime() & 0xf) == 3) {
            targetSpeed = getTargetSpeed();
        }
        if ((nonNullLevel().getGameTime() & 0x3f) == 3) {
            spawnFailures = Math.max(0, spawnFailures - 1);
        }
    }

private void coolHeatSinks() {
        if (grateRange >= 2) {
            int curTeIndex = (int) (pressureTube.nonNullLevel().getGameTime() % 27);
            BlockPos curPos = pressureTube.getBlockPos().relative(dir, 2).offset(-1 + curTeIndex % 3, -1 + curTeIndex / 3 % 3, -1 + curTeIndex / 9 % 3);
            BlockEntity te = pressureTube.nonNullLevel().getBlockEntity(curPos);
            if (te instanceof HeatSinkBlockEntity) heatSinks.add((HeatSinkBlockEntity) te);

            Iterator<HeatSinkBlockEntity> iterator = heatSinks.iterator();
            int tubesCooled = 0;
            while (iterator.hasNext()) {
                HeatSinkBlockEntity heatSink = iterator.next();
                if (heatSink.isRemoved()) {
                    iterator.remove();
                } else {
                    for (int i = 0; i < 4; i++) {
                        heatSink.onFannedByAirGrate();
                    }
                    tubesCooled++;
                }
            }
            if (tubesCooled > 0) {
                pressureTube.addAir(-(5 + (tubesCooled / 3)));
            }
        }
    }

