        } else {
            if (prevCamoState != camoState) {
                fakeFloorTextureUV = ClientUtils.getTextureUV(camoState, Direction.UP);
                fakeFloorTextureTint = camoState != null && camoState.getBlock() instanceof ColorHandlers.ITintableBlock t ?
                        0xFF000000 | t.getTintColor(camoState, level, getBlockPos(), 0) :
                        0xFFFFFFFF;
                prevCamoState = camoState;
            }
            if ((nonNullLevel().getGameTime() & 0xf) == 0) {
                // kludge to prevent elevator TER rendering unlit sometimes
                lightAbove = ClientUtils.getLightAt(worldPosition.above());
            }
        }

        double speedMultiplier = getEffectiveSpeedMultiplier();
        if (extension < targetExtension && !nonNullLevel().isClientSide && getPressure() < PneumaticValues.MIN_PRESSURE_ELEVATOR) {
            setTargetExtensionForConnectedElevators(extension);
            queueStateSyncForConnectedElevators();
        }

        double elevatorDelta = calculateElevatorDelta(extension, targetExtension, speedMultiplier);
        if (elevatorDelta != 0) {
            extension += elevatorDelta;

            if (elevatorDelta > 0) {
                addAir((int) (-elevatorDelta * PneumaticValues.USAGE_ELEVATOR * (getSpeedUsageMultiplierFromUpgrades() / speedMultiplier)));
            } else if (!nonNullLevel().isClientSide && chargingUpgrades > 0 && getPressure() < airHandler.getDangerPressure() - 0.1f) {
                float mul = 0.15f * Math.min(4, chargingUpgrades);
                addAir((int) (-elevatorDelta * PneumaticValues.USAGE_ELEVATOR * mul * (getSpeedUsageMultiplierFromUpgrades() / speedMultiplier)));
            }
        }

        moveEntitiesOnPlatform(extension - oldExtension);

        if (PneumaticCraftUtils.epsilonEquals(oldExtension, extension) && !isStopped) {
            // just arrived
            isStopped = true;
            ticksRunning = 0;
            playStopStartSound();
            if (!nonNullLevel().isClientSide) updateFloors(false);
        } else if (!PneumaticCraftUtils.epsilonEquals(oldExtension, extension) && isStopped) {
            // just departed
            isStopped = false;
            playStopStartSound();
        }
        if (!isStopped) ticksRunning++;
    }

@SubscribeEvent
        public static void onLeftClick(PlayerInteractEvent.LeftClickBlock event) {
            if (event.getItemStack().getItem() instanceof MemoryStickItem) {
                if (!event.getLevel().isClientSide) {
                    long now = event.getLevel().getGameTime();
                    long last = lastEvent.getOrDefault(event.getEntity().getUUID(), 0L);
                    if (now - last > 5) {
                        toggleXPAbsorption(event.getEntity(), event.getItemStack());
                        lastEvent.put(event.getEntity().getUUID(), now);
                    }
                }
                event.setCanceled(true);
            }
        }

@Override
    public void inventoryTick(ItemStack pStack, Level pLevel, Entity pEntity, int pSlotId, boolean pIsSelected) {
        if (pEntity.level().isClientSide) return;

        ChargeMode mode = getChargeMode(pStack);
        if (pEntity instanceof Player player && mode != ChargeMode.NONE && pLevel.getGameTime() % PneumaticValues.ARMOR_CHARGER_INTERVAL == 15) {
            PNCCapabilities.getAirHandler(pStack).ifPresent(srcHandler -> {
                for (ItemStack stack : mode.getStacksToCharge(player)) {
                    if (srcHandler.getPressure() < 0.1F) return;
                    if (stack.getCount() == 1 && stack != pStack && !isChargingAirCanister(stack)) {
                        tryChargeItem(srcHandler, stack, type.maxTransfer);
                    }
                }
            });
        }
    }

@Override
    public void tickServer() {
        super.tickServer();

        if (getMinigun().getAttackTarget() == null && rsController.shouldRun()) {
            getMinigun().setSweeping(true);
            if ((nonNullLevel().getGameTime() & 0xF) == 0) {
                List<LivingEntity> entities = nonNullLevel().getEntitiesOfClass(LivingEntity.class, getTargetingBoundingBox(), entitySelector);
                if (!entities.isEmpty()) {
                    entities.sort(new EntityDistanceComparator(getBlockPos()));
                    getMinigun().setAttackTarget(entities.getFirst());
                    targetEntityId = getMinigun().getAttackTarget().getId();
                } else if (targetEntityId > 0) {
                    getMinigun().setReturning(true);
                    targetEntityId = -1;
                }
            }
        } else {
            getMinigun().setSweeping(false);
        }
        LivingEntity target = getMinigun().getAttackTarget();
        if (target != null) {
            if (rsController.shouldRun() && entitySelector.test(target)) {
                if ((nonNullLevel().getGameTime() & 0x7) == 0) {
                    // Make sure any knockback has the right direction.
                    getFakePlayer().setPos(getBlockPos().getX() + 0.5, getBlockPos().getY() + 0.5, getBlockPos().getZ() + 0.5);
                    if (getMinigun().tryFireMinigun(target).ammoUsedUp()) {
                        clearEmptyAmmo();
                    }
                }
            } else {
                getMinigun().setAttackTarget(null);
                getMinigun().minigunYaw = idleYaw;
                targetEntityId = -1;
            }
        }
    }

